import { type FC, useCallback, useEffect, useMemo, useState } from 'react';
import { useIntl } from 'react-intl';

import { Grid } from '@hexa-ui/components';
import { Alert, StickyScrollWithFilters } from 'components';
import { useGlobalDataAvailability, useLastDataRefresh } from 'contexts';
import { FilterDataAccessor } from 'domain/Filter/FilterDataAccessor';
import { useBffData } from 'hooks';
import { PageTitle } from 'pages/components';
import {
  applyFilters,
  loadFilters,
  updateFormValue,
} from 'redux/slices/filters';
import { StyledGridContainer } from 'shared/Styles';

import { FILTER_CONFIGS, GLOBAL_ZONE } from '../../constants';
import { OverTimePerformance } from './components/OverTimePerformance';
import { PosPerformance } from './components/PosPerformance';
import { usePosToolFilters } from './hooks';
import {
  mapOverTimePerformanceCards,
  mapPosPerformanceChart,
  POS_TOOL_OVERVIEW_COMPONENT_ID,
} from './utils';

const POS_OVERVIEW_PERIODS_COUNT = 8;

const POS_TIME_FRAME_MAP: Record<string, string> = {
  QTD: 'QTR',
};

export const Overview: FC = () => {
  const { formatMessage } = useIntl();
  const { shouldShowGlobalBanner } = useGlobalDataAvailability();
  const { applied, isLoaded, isError, dataFilters, dispatch } =
    usePosToolFilters();
  const { lastDataRefreshKpisDateMonthYear } = useLastDataRefresh();
  const [initialFiltersLoaded, setInitialFiltersLoaded] = useState(false);

  useEffect(() => {
    globalThis.scrollTo?.(0, 0);
  }, []);

  useEffect(() => {
    if (initialFiltersLoaded || !isLoaded) return;

    if (!applied?.country) {
      dispatch(updateFormValue({ key: 'zone', value: GLOBAL_ZONE }));
      dispatch(updateFormValue({ key: 'country', value: GLOBAL_ZONE }));
      dispatch(applyFilters());
    }

    setInitialFiltersLoaded(true);
  }, [initialFiltersLoaded, isLoaded, applied?.country, dispatch]);

  const posRefreshDate = lastDataRefreshKpisDateMonthYear?.pos ?? '';
  const posPeriod = String(applied?.pos_periods ?? '');

  const shouldSkipRequest =
    !initialFiltersLoaded ||
    !applied?.zone ||
    !applied?.country ||
    !applied?.segments ||
    !applied?.pos_periods ||
    !posRefreshDate;

  const { data, loading, error, refetch } = useBffData({
    id: 'category_pos-performance-tool_overview_overtime-performance',
    kpiGroup: 'pos',
    subFilters: {
      country: String(applied?.country ?? ''),
      category: String(applied?.segments ?? ''),
      time_frame: POS_TIME_FRAME_MAP[posPeriod] ?? posPeriod,
      periods: POS_OVERVIEW_PERIODS_COUNT,
    },
    skipMainFilters: true,
    skipRequest: !isLoaded || shouldSkipRequest,
  });

  const hasError = Boolean(error) || Boolean(isError);
  const isLoading = (!isLoaded || loading) && !hasError;

  const handleRetry = useCallback(() => {
    dispatch(loadFilters({ pageName: FILTER_CONFIGS.pageName }));
    refetch();
  }, [dispatch, refetch]);

  const overviewData = isLoading
    ? undefined
    : data?.[POS_TOOL_OVERVIEW_COMPONENT_ID];
  const bigNumbers = mapOverTimePerformanceCards(overviewData);
  const chartData = mapPosPerformanceChart(overviewData);

  const countryLabel = useMemo(() => {
    if (!dataFilters || !applied) return 'Global';
    const country = FilterDataAccessor.getInstance().getCountry(
      dataFilters,
      applied,
    );
    return country?.label === 'All' || !country?.label
      ? 'Global'
      : country.label;
  }, [dataFilters, applied]);

  const categoryLabel = useMemo(() => {
    if (!applied?.segments) return 'Alcohol';

    const segmentsOptions = dataFilters?.segments?.values;

    if (!Array.isArray(segmentsOptions) || segmentsOptions.length === 0) {
      return String(applied.segments);
    }

    const match = segmentsOptions.find((opt) => opt.value === applied.segments);

    return match?.label ? String(match.label) : String(applied.segments);
  }, [applied?.segments, dataFilters]);
  const pageTitle = `${countryLabel} ${categoryLabel} Category`;

  return (
    <>
      <StickyScrollWithFilters
        filter={{
          pageName: FILTER_CONFIGS.pageName,
          visibleFields: FILTER_CONFIGS.visibleFields,
        }}
        breadcrumbs={{
          showIcon: true,
          pageList: [
            {
              pageName: formatMessage({ id: 'Pillars.pageName.category' }),
              href: '/category',
            },
            {
              pageName: formatMessage({ id: 'Category.POSTool.title' }),
              href: '',
            },
          ],
          dataTestId: 'breadcrumbs-pos-tool-overview',
        }}
        dataTestId="filter-pos-tool-overview"
      />

      <StyledGridContainer>
        <Grid.Item
          xs={12}
          sm={12}
          md={12}
          lg={12}
          xl={12}
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 16,
          }}
        >
          {shouldShowGlobalBanner('pos') && (
            <Alert
              type="warning"
              position="inline"
              title={formatMessage({ id: 'GlobalData.bannerTitle' })}
              message={formatMessage({ id: 'GlobalData.bannerMessage' })}
              dataTestId="global-data-banner-pos"
            />
          )}
          <PageTitle
            title={pageTitle}
            description={formatMessage({
              id: 'Category.POSTool.description',
            })}
            dataTestId="page-title-pos-tool-overview"
          />
          <OverTimePerformance
            bigNumbers={bigNumbers}
            isLoading={isLoading}
            error={hasError}
            onRetry={handleRetry}
            dataTestId="pos-tool-overview"
          />
          <PosPerformance
            chartData={chartData}
            dataTestId="pos-tool-overview"
            error={hasError}
            isLoading={isLoading}
            onRetry={handleRetry}
          />
        </Grid.Item>
      </StyledGridContainer>
    </>
  );
};
